CREATE TABLE "WW_CATEGORIES"
(
	"ID" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
	"TITLE" VARCHAR2(255),
	"ORDERING" NUMBER(10),
	"PARAMS" VARCHAR2(4000)
);




CREATE TABLE "WW_FLOWER"
(
	"ID" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
	"CATID" NUMBER(10) DEFAULT 0,
	"TITLE" VARCHAR2(255),
	"MEANING" VARCHAR2(4000),
	"ORDERING" NUMBER(10),
	"STATE" NUMBER(3),
	"PARAMS" VARCHAR2(4000)
);




CREATE TABLE "WW_NESTEDSETS"
(
	"ID" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
	"PARENT_ID" NUMBER(19),
	"LFT" NUMBER(10),
	"RGT" NUMBER(10),
	"LEVEL" NUMBER(19),
	"TITLE" VARCHAR2(255),
	"ALIAS" VARCHAR2(255),
	"ACCESS" VARCHAR2(4000),
	"PATH" VARCHAR2(255)
);

ALTER TABLE "WW_CATEGORIES" MODIFY ("ID" GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));

ALTER TABLE "WW_FLOWER" MODIFY ("ID" GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));

ALTER TABLE "WW_NESTEDSETS" MODIFY ("ID" GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
